export default function DataTableExample() {
  const table = useTable({
    features,
    columns,
    data: records,
    getRowId: (row) => row.id,
    initialState: { pagination: { pageIndex: 0, pageSize: 2 } },
  });
  const filterValue = table.getColumn('name')?.getFilterValue();
  const filter = typeof filterValue === 'string' ? filterValue : '';
  const headerGroups = table.getHeaderGroups().map((group) => (
    <TableRow key={group.id}>
      {group.headers.map((header) => (
        <TableHead aria-sort={sortDirection(header.column.getIsSorted())} key={header.id}>
          {header.isPlaceholder === true ? null : <table.FlexRender header={header} />}
        </TableHead>
      ))}
    </TableRow>
  ));
  const emptyRow = (
    <TableRow>
      <TableCell className="text-center" colSpan={table.getVisibleLeafColumns().length}>
        No matching records.
      </TableCell>
    </TableRow>
  );
  const rows = table.getRowModel().rows.map((row) => (
    <TableRow data-state={row.getIsSelected() === true ? 'selected' : undefined} key={row.id}>
      {row.getVisibleCells().map((cell) => (
        <TableCell key={cell.id}>
          <table.FlexRender cell={cell} />
        </TableCell>
      ))}
    </TableRow>
  ));
  const body = table.getRowModel().rows.length === 0 ? emptyRow : rows;
  return (
    <div className="min-w-0 space-y-4">
      <div className="flex min-w-0 flex-wrap items-center gap-2">
        <Field className="min-w-0 flex-1">
          <Input
            aria-label="Filter sample records"
            className="min-w-0 flex-1"
            onChange={(event) => table.getColumn('name')?.setFilterValue(event.currentTarget.value)}
            placeholder="Filter names"
            value={filter}
          />
        </Field>
        <Menu>
          <MenuTrigger
            render={
              <Button type="button" variant="outline">
                Visible columns
              </Button>
            }
          />
          <MenuContent>
            {table
              .getAllColumns()
              .filter((column) => column.getCanHide())
              .map((column) => (
                <MenuCheckboxItem
                  checked={column.getIsVisible()}
                  key={column.id}
                  onCheckedChange={(checked) => column.toggleVisibility(checked)}
                  value={column.id}
                >
                  {column.id}
                </MenuCheckboxItem>
              ))}
          </MenuContent>
        </Menu>
      </div>
      <Table aria-label="Sample records">
        <TableHeader>{headerGroups}</TableHeader>
        <TableBody>{body}</TableBody>
      </Table>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <output aria-label="Selected record count" className="text-sm">
          {table.getSelectedRowModel().rows.length} selected
        </output>
        <div className="flex flex-wrap gap-2">
          <Button
            disabled={table.getCanPreviousPage() !== true}
            onClick={() => table.previousPage()}
            type="button"
            variant="outline"
          >
            Previous records
          </Button>
          <Button
            disabled={table.getCanNextPage() !== true}
            onClick={() => table.nextPage()}
            type="button"
            variant="outline"
          >
            Next records
          </Button>
        </div>
      </div>
    </div>
  );
}

'use client';
import type { AsyncOptionsStatus } from '@ui-sdk/core/async-options';
import type { ComboboxController } from '@ui-sdk/core/combobox';
import { SearchIcon, XIcon } from 'lucide-react';
import type React from 'react';
import { groupOptions, resolveLabel } from '@/components/ui/shared/combobox-options';
import { definedProps } from '@/registry/base-nova/protoform/lib/sdk-props';
import { cn } from '@/registry/base-nova/protoform/lib/utils';
import type { SharedProps } from '@/registry/base-nova/protoform/lib/utils/index';
import {
  Combobox,
  ComboboxClear,
  ComboboxContent,
  ComboboxCreate,
  ComboboxEmpty,
  ComboboxGroup,
  ComboboxGroupLabel,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
  ComboboxStatus,
} from './parts';

export interface ComboboxOption {
  data?: unknown;
  disabled?: boolean | undefined;
  group?: string | undefined;
  groupTestId?: string | undefined;
  label: string;
  testId?: string | undefined;
  value: string;
}
export interface OptionComboboxProps extends React.AriaAttributes, SharedProps {
  className?: string | undefined;
  clearable?: boolean | undefined;
  controller?: ComboboxController | undefined;
  creatable?: boolean | undefined;
  createLabel?: string | undefined;
  disabled?: boolean | undefined;
  emptyState?: React.ReactNode;
  filter?: boolean | undefined;
  footer?: React.ReactNode;
  id?: string | undefined;
  inputTestId?: string | undefined;
  loading?: boolean | undefined;
  modal?: boolean | 'pointer' | undefined;
  onChange: (value: string) => void;
  onCreateOption?: ((value: string) => void) | undefined;
  onInputValueChange?: ((value: string) => void) | undefined;
  onLoadMore?: (() => void) | undefined;
  options: readonly ComboboxOption[];
  placeholder?: string | undefined;
  renderOption?: ((option: ComboboxOption) => React.ReactNode) | undefined;
  status?: AsyncOptionsStatus | undefined;
  value?: string | undefined;
}
export function OptionCombobox({
  options,
  controller,
  footer,
  value,
  onChange,
  onInputValueChange,
  onLoadMore,
  disabled,
  loading = false,
  status,
  modal,
  filter = true,
  clearable = true,
  creatable,
  onCreateOption,
  createLabel = 'Create',
  emptyState = 'No options found.',
  renderOption,
  placeholder,
  inputTestId,
  testId,
  className,
  ...inputProps
}: OptionComboboxProps) {
  const groups = groupOptions(options);
  const isLoading = status === undefined ? loading === true : status === 'loading';
  function renderOptions(items: readonly ComboboxOption[]) {
    return items.map((option) => (
      <ComboboxItem
        disabled={option.disabled}
        key={option.value}
        label={option.label}
        testId={option.testId}
        value={option.value}
      >
        {renderOption === undefined ? option.label : renderOption(option)}
      </ComboboxItem>
    ));
  }
  return (
    <Combobox
      autoHighlight="always"
      {...definedProps({
        onQueryChange: (query: string, details: { reason: string; source: string }) => {
          if (details.reason === 'input-change' || details.reason === 'clear-press' || details.source === 'agent') {
            onInputValueChange?.(query);
          }
        },
        onLoadMore,
        controller,
        disabled,
        modal,
      })}
      itemToLabel={(item) => resolveLabel(options, item)}
      onValueChange={(next) => onChange(next ?? '')}
      status={status ?? (isLoading ? 'loading' : 'idle')}
      value={value ?? null}
      {...(filter === true ? {} : { filter: false })}
    >
      <div className={cn('relative', className)}>
        <SearchIcon
          aria-hidden="true"
          className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
        />
        <ComboboxInput
          {...definedProps(inputProps)}
          placeholder={placeholder}
          testId={inputTestId ?? testId}
          variant="search"
        />
        {clearable === true ? (
          <ComboboxClear aria-label="Clear selection" className="absolute top-1/2 right-2 -translate-y-1/2">
            <XIcon aria-hidden="true" className="size-3.5" />
          </ComboboxClear>
        ) : null}
      </div>
      <ComboboxContent>
        <ComboboxList>
          {groups === undefined
            ? renderOptions(options)
            : groups.map((group) => (
                <ComboboxGroup key={group.heading}>
                  <ComboboxGroupLabel testId={group.testId}>{group.heading}</ComboboxGroupLabel>
                  {renderOptions(group.options)}
                </ComboboxGroup>
              ))}
          {creatable === true ? (
            <ComboboxCreate
              onCreate={(query) => {
                onCreateOption?.(query);
                onChange(query);
                return query;
              }}
            >
              {(state) => `${createLabel} ${state.query}`}
            </ComboboxCreate>
          ) : null}
        </ComboboxList>
        {isLoading ? <ComboboxStatus>Loading…</ComboboxStatus> : <ComboboxEmpty>{emptyState}</ComboboxEmpty>}
        {footer}
      </ComboboxContent>
    </Combobox>
  );
}

export type UIProps<T> = { [K in keyof T]: T[K] | (Pick<T, K> extends Required<Pick<T, K>> ? never : undefined) };
type DefinedProps<T> = {
  [K in keyof T as undefined extends T[K] ? never : K]: T[K];
} & {
  [K in keyof T as undefined extends T[K] ? K : never]?: Exclude<T[K], undefined>;
};
function hasDefinedValues<T extends object>(props: T): props is T & DefinedProps<T> {
  return Reflect.ownKeys(props).every((key) => Reflect.get(props, key) !== undefined);
}
export function definedProps<T extends object>(props: T): DefinedProps<T> {
  const result = { ...props };
  for (const key of Reflect.ownKeys(result)) {
    if (Reflect.get(result, key) === undefined) {
      Reflect.deleteProperty(result, key);
    }
  }
  if (hasDefinedValues(result)) {
    return result;
  }
  throw new TypeError('Could not normalize UI properties.');
}

